#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
umask 077
mkdir -p .local
if [ -f .local/platform.env ]; then
  # This file is generated by this script and readable only by the server user.
  source .local/platform.env
else
  PLATFORM_ADMIN_TOTP_SECRET=$(openssl rand -hex 20 | python3 -c 'import base64,sys; print(base64.b32encode(bytes.fromhex(sys.stdin.read().strip())).decode())')
  printf 'export PLATFORM_ADMIN_TOTP_SECRET=%q\nexport PUBLIC_REGISTRATION_ENABLED=false\n' "$PLATFORM_ADMIN_TOTP_SECRET" > .local/platform.env
  chmod 600 .local/platform.env
fi
export PLATFORM_ADMIN_TOTP_SECRET
export PUBLIC_REGISTRATION_ENABLED=false
export PLATFORM_BOOTSTRAP_ENABLED=true
read -r -p 'Choose your Super Admin username: ' PLATFORM_ADMIN_USERNAME
read -r -s -p 'Choose a Super Admin password (at least 14 characters): ' PLATFORM_ADMIN_PASSWORD
printf '\n'
export PLATFORM_ADMIN_USERNAME PLATFORM_ADMIN_PASSWORD
printf '%s\n' 'Add this key manually to Google/Microsoft Authenticator (time based, 6 digits):'
printf '%s\n' "$PLATFORM_ADMIN_TOTP_SECRET"
printf '%s\n' 'Keep this key private. It is saved in ignored .local/platform.env; back it up securely.'
printf '%s\n' 'Open http://localhost:4174/admin/login after the API starts.'
exec bash scripts/start-local.sh "$@"
